import { Test, TestingModule } from '@nestjs/testing';
import { AppController } from './app.controller';
import { AppService } from './app.service';

describe('AppController', () => {
  let appController: AppController;

  beforeEach(async () => {
    const app: TestingModule = await Test.createTestingModule({
      controllers: [AppController],
      providers: [AppService],
    }).compile();

    appController = app.get<AppController>(AppController);
  });

  describe('logMessage', () => {
    it('should log a message', async () => {
      const response = await appController.logMessage({ message: 'Test log message' });
      expect(response).toEqual({ message: 'Log message successful' });
    });
  });

  describe('getLogs', () => {
    it('should retrieve logs', async () => {
      const logs = await appController.getLogs();
      expect(typeof logs).toBe('string');
    });
  });
});
</CODE>

<FILEPATH>
src/app.controller.ts
</FILEPATH>
<CODE>
import { Controller, Get, Post, Body, BadRequestException } from '@nestjs/common';
import { AppService } from './app.service';

@Controller()
export class AppController {
  constructor(private readonly appService: AppService) {}

  @Post('log')
  async logMessage(@Body() body: { message: string }): Promise<{ message: string }> {
    if (!body.message || typeof body.message !== 'string') {
      throw new BadRequestException('Invalid message');
    }
    await this.appService.logMessage(body.message);
    return { message: 'Log message successful' };
  }

  @Get('logs')
  async getLogs(): Promise<string> {
    return this.appService.getLogs();
  }
}
</CODE>

